<?php

namespace App\Pos\Service;

use Stringable;

/**
 * RequestManager
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class PosItemManager implements Stringable {

    public function __construct(private $name = '', private $quantity = '', private $price = '', private $dollarSign = '')
    {
    }

    public function __toString(): string {
        $rightCols = 10;
        $leftCols = 48;
        if($this -> dollarSign) {
            $leftCols = $leftCols / 2 - $rightCols / 2;
        }
        $left = str_pad($this -> name, $leftCols) ;
        $center = $this -> quantity ;

        $sign = ($this -> dollarSign ? '৳' : '');
        $right = str_pad($sign . $this -> price, $rightCols, ' ', STR_PAD_LEFT);
        return "$left$center$right\n";
    }
}
